import{_ as t,a0 as o,w as d,s as r,ao as l,I as n,x as a,a1 as i,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"使用 LVM 为你的 Fedora 系统添加存储 | LCTT x X-CMD","titleTemplate":false,"description":"使用 LVM 为你的 Fedora 系统添加存储 | LCTT (202012) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 LVM 为你的 Fedora 系统添加存储 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 LVM 为你的 Fedora 系统添加存储 | LCTT (202012) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202012/20201207 Add storage to your Fedora system with LVM","title":"使用 LVM 为你的 Fedora 系统添加存储","tag":"202012","desc":""},"relativePath":"202012/20201207 Add storage to your Fedora system with LVM.md","filePath":"[post].md"}'),c={name:"202012/20201207 Add storage to your Fedora system with LVM.md"};function g(u,s,h,b,k,f){const e=o("Link");return d(),r("div",null,[s[29]||(s[29]=l('<h1 id="使用-lvm-为你的-fedora-系统添加存储" tabindex="-1">使用 LVM 为你的 Fedora 系统添加存储 <a class="header-anchor" href="#使用-lvm-为你的-fedora-系统添加存储" aria-label="Permalink to “使用 LVM 为你的 Fedora 系统添加存储”">​</a></h1><p><img src="https://fedoramagazine.org/wp-content/uploads/2020/11/lvm-add-disk-816x345.jpg" alt=""></p><p>有时需要在系统中添加另一块磁盘。这就是<ruby>逻辑卷管理<rt>Logical Volume Management</rt></ruby>（LVM）的用武之地。LVM 的好处之处在于它相当灵活。有几种方法可以添加一块磁盘。这篇文章介绍了一种方法。</p><h3 id="注意" tabindex="-1">注意！ <a class="header-anchor" href="#注意" aria-label="Permalink to “注意！”">​</a></h3><p>这篇文章并不包括将新的磁盘物理地安装到系统中的过程。请查阅你的系统和磁盘文档，了解如何正确地进行安装。</p><p><strong>重要：</strong> 一定要确保你已经备份重要数据。如果新磁盘已有数据，那么本文中描述的步骤将破坏数据。</p><h3 id="最好了解" tabindex="-1">最好了解 <a class="header-anchor" href="#最好了解" aria-label="Permalink to “最好了解”">​</a></h3>',7)),n("p",null,[s[1]||(s[1]=a("本文并没有深入介绍 LVM 的每一个功能，重点是添加磁盘。但基本上你要了解，LVM 有",-1)),s[2]||(s[2]=n("ruby",null,[a("卷组"),n("rt",null,"volume group")],-1)),s[3]||(s[3]=a("（VG），它由一个或多个分区和/或磁盘组成。你把这些分区或磁盘以",-1)),s[4]||(s[4]=n("ruby",null,[a("物理卷"),n("rt",null,"physical volume")],-1)),s[5]||(s[5]=a("（PV）的方式添加到卷组。一个卷组可以分成许多",-1)),s[6]||(s[6]=n("ruby",null,[a("逻辑卷"),n("rt",null,"logical volume")],-1)),s[7]||(s[7]=a("（LV）。逻辑卷可以作为文件系统、ramdisk 等其他存储使用。更多信息可以在",-1)),i(e,{href:"https://en.wikipedia.org/wiki/Logical_Volume_Manager_(Linux)"},{default:p(()=>[...s[0]||(s[0]=[a("这里",-1)])]),_:1}),s[8]||(s[8]=a("中找到。",-1))]),s[30]||(s[30]=l(`<p>可以看作是，把物理卷形成一个存储池（一个卷组），然后从这个存储池中划分出逻辑卷，供你的系统直接使用。</p><h3 id="准备" tabindex="-1">准备 <a class="header-anchor" href="#准备" aria-label="Permalink to “准备”">​</a></h3><p>确保你能看到你要添加的磁盘。在添加磁盘之前使用 <code>lsblk</code> 查看哪些存储空间已经可用或正在使用。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lsblk</span></span>
<span class="line"><span>NAME                   MAJ:MIN RM  SIZE RO TYPE MOUNTPOINT</span></span>
<span class="line"><span>zram0                  251:0    0  989M  0 disk [SWAP]</span></span>
<span class="line"><span>vda                    252:0    0   20G  0 disk</span></span>
<span class="line"><span>├─vda1                 252:1    0    1G  0 part /boot</span></span>
<span class="line"><span>└─vda2                 252:2    0   19G  0 part</span></span>
<span class="line"><span>└─fedora_fedora-root   253:0    0   19G  0 lvm  /</span></span></code></pre></div><p>本文使用的是带有虚拟存储的虚拟机，因此设备名称以 <code>vda</code> 开头代表第一个磁盘，<code>vdb</code> 代表第二个磁盘，以此类推。你的设备名称可能不同。许多系统会将 <code>sda</code> 作为第一个物理磁盘，<code>sdb</code> 代表第二个磁盘，以此类推。</p><p>当已连接新磁盘，并且你的系统已备份且正在运行，再次使用 <code>lsblk</code> 来查看新的块设备。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lsblk</span></span>
<span class="line"><span>NAME                   MAJ:MIN RM  SIZE RO TYPE MOUNTPOINT</span></span>
<span class="line"><span>zram0                  251:0    0  989M  0 disk [SWAP]</span></span>
<span class="line"><span>vda                    252:0    0   20G  0 disk</span></span>
<span class="line"><span>├─vda1                 252:1    0    1G  0 part /boot</span></span>
<span class="line"><span>└─vda2                 252:2    0   19G  0 part</span></span>
<span class="line"><span>└─fedora_fedora-root 253:0    0   19G  0 lvm  /</span></span>
<span class="line"><span>vdb                    252:16   0   10G  0 disk</span></span></code></pre></div><p>现在有一个名为 <code>vdb</code> 的新设备。该设备的位置是 <code>/dev/vdb</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l /dev/vdb</span></span>
<span class="line"><span>brw-rw----. 1 root disk 252, 16 Nov 24 12:56 /dev/vdb</span></span></code></pre></div>`,9)),n("p",null,[s[10]||(s[10]=a("我们可以看到磁盘，但我们还不能用 LVM 来使用它。如果你运行 ",-1)),s[11]||(s[11]=n("code",null,"blkid",-1)),s[12]||(s[12]=a("，你应该不会看到它被列出。对于这个和之后的命令，你需要确保你的系统",-1)),i(e,{href:"https://fedoramagazine.org/howto-use-sudo/"},{default:p(()=>[...s[9]||(s[9]=[a("已配置好，这样你可以使用 sudo",-1)])]),_:1}),s[13]||(s[13]=a("：",-1))]),s[31]||(s[31]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo blkid</span></span>
<span class="line"><span>/dev/vda1: UUID=&quot;4847cb4d-6666-47e3-9e3b-12d83b2d2448&quot; BLOCK_SIZE=&quot;4096&quot; TYPE=&quot;ext4&quot; PARTUUID=&quot;830679b8-01&quot;</span></span>
<span class="line"><span>/dev/vda2: UUID=&quot;k5eWpP-6MXw-foh5-Vbgg-JMZ1-VEf9-ARaGNd&quot; TYPE=&quot;LVM2_member&quot; PARTUUID=&quot;830679b8-02&quot;</span></span>
<span class="line"><span>/dev/mapper/fedora_fedora-root: UUID=&quot;f8ab802f-8c5f-4766-af33-90e78573f3cc&quot; BLOCK_SIZE=&quot;4096&quot; TYPE=&quot;ext4&quot;</span></span>
<span class="line"><span>/dev/zram0: UUID=&quot;fc6d7a48-2bd5-4066-9bcf-f062b61f6a60&quot; TYPE=&quot;swap&quot;</span></span></code></pre></div><h3 id="将磁盘添加到-lvm-中" tabindex="-1">将磁盘添加到 LVM 中 <a class="header-anchor" href="#将磁盘添加到-lvm-中" aria-label="Permalink to “将磁盘添加到 LVM 中”">​</a></h3><p>使用 <code>pvcreate</code> 初始化磁盘。你需要传递设备的完整路径。在这个例子中，它是 <code>/dev/vdb</code>。在你的系统中，它可能是 <code>/dev/sdb</code> 或其他设备名。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo pvcreate /dev/vdb</span></span>
<span class="line"><span>Physical volume &quot;/dev/vdb&quot; successfully created.</span></span></code></pre></div><p>当你运行 <code>blkid</code> 时，你应该看到磁盘已经被初始化为一个 <code>LVM2_member</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo blkid</span></span>
<span class="line"><span>/dev/vda1: UUID=&quot;4847cb4d-6666-47e3-9e3b-12d83b2d2448&quot; BLOCK_SIZE=&quot;4096&quot; TYPE=&quot;ext4&quot; PARTUUID=&quot;830679b8-01&quot;</span></span>
<span class="line"><span>/dev/vda2: UUID=&quot;k5eWpP-6MXw-foh5-Vbgg-JMZ1-VEf9-ARaGNd&quot; TYPE=&quot;LVM2_member&quot; PARTUUID=&quot;830679b8-02&quot;</span></span>
<span class="line"><span>/dev/mapper/fedora_fedora-root: UUID=&quot;f8ab802f-8c5f-4766-af33-90e78573f3cc&quot; BLOCK_SIZE=&quot;4096&quot; TYPE=&quot;ext4&quot;</span></span>
<span class="line"><span>/dev/zram0: UUID=&quot;fc6d7a48-2bd5-4066-9bcf-f062b61f6a60&quot; TYPE=&quot;swap&quot;</span></span>
<span class="line"><span>/dev/vdb: UUID=&quot;4uUUuI-lMQY-WyS5-lo0W-lqjW-Qvqw-RqeroE&quot; TYPE=&quot;LVM2_member&quot;</span></span></code></pre></div><p>你可以使用 <code>pvs</code> 列出当前所有可用的物理卷：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo pvs</span></span>
<span class="line"><span>PV         VG            Fmt  Attr PSize   PFree</span></span>
<span class="line"><span>/dev/vda2  fedora_fedora lvm2 a--  &lt;19.00g     0</span></span>
<span class="line"><span>/dev/vdb                 lvm2 ---   10.00g 10.00g</span></span></code></pre></div><p><code>/dev/vdb</code> 被列为一个 PV （物理卷），但还没有分配到一个 VG （卷组）。</p><h3 id="将物理卷添加到一个卷组" tabindex="-1">将物理卷添加到一个卷组 <a class="header-anchor" href="#将物理卷添加到一个卷组" aria-label="Permalink to “将物理卷添加到一个卷组”">​</a></h3><p>你可以使用 <code>vgs</code> 找到可用的卷组列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vgs</span></span>
<span class="line"><span>VG            #PV #LV #SN Attr   VSize   VFree</span></span>
<span class="line"><span>fedora_fedora   1   1   0 wz--n- 19.00g    0</span></span></code></pre></div><p>在本例中，只有一个卷组可用。接下来，将物理卷添加到 <code>fedora_fedora</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vgextend fedora_fedora /dev/vdb</span></span>
<span class="line"><span>Volume group &quot;fedora_fedora&quot; successfully extended</span></span></code></pre></div><p>你现在应该看到物理卷已被添加到卷组中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo pvs </span></span>
<span class="line"><span>PV        VG            Fmt  Attr PSize   PFree</span></span>
<span class="line"><span>/dev/vda2 fedora_fedora lvm2 a–   &lt;19.00g 0</span></span>
<span class="line"><span>/dev/vdb  fedora_fedora lvm2 a–   &lt;10.00g &lt;10.00g</span></span></code></pre></div><p>看一下卷组：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vgs</span></span>
<span class="line"><span>VG            #PV #LV #SN Attr  VSize  VFree</span></span>
<span class="line"><span>fedora_fedora 2   1   0   wz–n- 28.99g &lt;10.00g</span></span></code></pre></div><p>你也可以获得具体卷组和物理卷的详细列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vgdisplay fedora_fedora</span></span>
<span class="line"><span>--- Volume group ---</span></span>
<span class="line"><span>VG Name               fedora_fedora</span></span>
<span class="line"><span>System ID</span></span>
<span class="line"><span>Format                lvm2</span></span>
<span class="line"><span>Metadata Areas        2</span></span>
<span class="line"><span>Metadata Sequence No  3</span></span>
<span class="line"><span>VG Access             read/write</span></span>
<span class="line"><span>VG Status             resizable</span></span>
<span class="line"><span>MAX LV                0</span></span>
<span class="line"><span>Cur LV                1</span></span>
<span class="line"><span>Open LV               1</span></span>
<span class="line"><span>Max PV                0</span></span>
<span class="line"><span>Cur PV                2</span></span>
<span class="line"><span>Act PV                2</span></span>
<span class="line"><span>VG Size               28.99 GiB</span></span>
<span class="line"><span>PE Size               4.00 MiB</span></span>
<span class="line"><span>Total PE              7422</span></span>
<span class="line"><span>Alloc PE / Size       4863 / 19.00 GiB</span></span>
<span class="line"><span>Free  PE / Size       2559 / 10.00 GiB</span></span>
<span class="line"><span>VG UUID               C5dL2s-dirA-SQ15-TfQU-T3yt-l83E-oI6pkp</span></span></code></pre></div><p>看下物理卷：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo pvdisplay /dev/vdb</span></span>
<span class="line"><span>--- Physical volume ---</span></span>
<span class="line"><span>PV Name               /dev/vdb</span></span>
<span class="line"><span>VG Name               fedora_fedora</span></span>
<span class="line"><span>PV Size               10.00 GiB / not usable 4.00 MiB</span></span>
<span class="line"><span>Allocatable           yes</span></span>
<span class="line"><span>PE Size               4.00 MiB</span></span>
<span class="line"><span>Total PE              2559</span></span>
<span class="line"><span>Free PE               2559</span></span>
<span class="line"><span>Allocated PE          0</span></span>
<span class="line"><span>PV UUID               4uUUuI-lMQY-WyS5-lo0W-lqjW-Qvqw-RqeroE</span></span></code></pre></div><p>现在我们已经添加了磁盘，我们可以为逻辑卷 （LV） 分配空间：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lvs</span></span>
<span class="line"><span>LV VG Attr LSize Pool Origin Data% Meta% Move Log Cpy%Sync Convert</span></span>
<span class="line"><span>root fedora_fedora -wi-ao---- 19.00g</span></span></code></pre></div><p>看一下逻辑卷。下面是详细的逻辑卷信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lvdisplay fedora_fedora/root</span></span>
<span class="line"><span>--- Logical volume ---</span></span>
<span class="line"><span>LV Path                /dev/fedora_fedora/root</span></span>
<span class="line"><span>LV Name                root</span></span>
<span class="line"><span>VG Name                fedora_fedora</span></span>
<span class="line"><span>LV UUID                yqc9cw-AvOw-G1Ni-bCT3-3HAa-qnw3-qUSHGM</span></span>
<span class="line"><span>LV Write Access        read/write</span></span>
<span class="line"><span>LV Creation host, time fedora, 2020-11-24 11:44:36 -0500</span></span>
<span class="line"><span>LV Status              available</span></span>
<span class="line"><span>LV Size                19.00 GiB</span></span>
<span class="line"><span>Current LE             4863</span></span>
<span class="line"><span>Segments               1</span></span>
<span class="line"><span>Allocation             inherit</span></span>
<span class="line"><span>Read ahead sectors     auto</span></span>
<span class="line"><span>- currently set to     256</span></span>
<span class="line"><span>Block device           253:0</span></span></code></pre></div><p>查看根文件系统（<code>/</code>）的大小，并将它与逻辑卷大小进行比较。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ df -h /</span></span>
<span class="line"><span>Filesystem                      Size  Used Avail Use% Mounted on</span></span>
<span class="line"><span>/dev/mapper/fedora_fedora-root   19G  1.4G   17G   8% /</span></span></code></pre></div><p>逻辑卷和文件系统大小都为 19G。让我们给根逻辑卷（<code>root</code>）增加 5G。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lvresize -L +5G fedora_fedora/root</span></span>
<span class="line"><span>Size of logical volume fedora_fedora/root changed from 19.00 GiB (4863 extents) to 24.00 GiB (6143 extents).</span></span>
<span class="line"><span>Logical volume fedora_fedora/root successfully resized.</span></span></code></pre></div><p>我们现在有 24G 的逻辑卷可用。看看根文件系统（<code>/</code>）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ df -h /</span></span>
<span class="line"><span>Filesystem                      Size  Used Avail Use% Mounted on</span></span>
<span class="line"><span>/dev/mapper/fedora_fedora-root   19G  1.4G   17G   8% /</span></span></code></pre></div><p>我们仍然显示只有 19G 的空闲空间，这是因为逻辑卷与文件系统不一样。要使用增加到逻辑卷的新空间，请调整文件系统的大小。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo resize2fs /dev/fedora_fedora/root</span></span>
<span class="line"><span>resize2fs 1.45.6 (20-Mar-2020)</span></span>
<span class="line"><span>Filesystem at /dev/fedora_fedora/root is mounted on /; on-line resizing required</span></span>
<span class="line"><span>old_desc_blocks = 3, new_desc_blocks = 3</span></span>
<span class="line"><span>The filesystem on /dev/fedora_fedora/root is now 6290432 (4k) blocks long.</span></span></code></pre></div><p>看看文件系统的大小。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ df -h /</span></span>
<span class="line"><span>Filesystem                      Size  Used Avail Use% Mounted on</span></span>
<span class="line"><span>/dev/mapper/fedora_fedora-root   24G  1.4G   21G   7% /</span></span></code></pre></div><p>正如你所看到的，根文件系统（<code>/</code>）已经占用了逻辑卷上的所有可用空间，而且不需要重新启动。</p><p>现在你已经将一个磁盘初始化为物理卷，并使用新的物理卷扩展了卷组。之后，你增加了逻辑卷的大小，并调整了文件系统的大小，以使用逻辑卷的新空间。</p><hr>`,39)),n("p",null,[s[15]||(s[15]=a("via: ",-1)),i(e,{href:"https://fedoramagazine.org/add-storage-to-your-fedora-system-with-lvm/"},{default:p(()=>[...s[14]||(s[14]=[a("https://fedoramagazine.org/add-storage-to-your-fedora-system-with-lvm/",-1)])]),_:1})]),n("p",null,[s[20]||(s[20]=a("作者：",-1)),i(e,{href:"https://fedoramagazine.org/author/maztaim/"},{default:p(()=>[...s[16]||(s[16]=[a("Tim Bosse",-1)])]),_:1}),s[21]||(s[21]=a(" 选题：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[17]||(s[17]=[a("lujun9972",-1)])]),_:1}),s[22]||(s[22]=a(" 译者：",-1)),i(e,{href:"https://github.com/geekpi"},{default:p(()=>[...s[18]||(s[18]=[a("geekpi",-1)])]),_:1}),s[23]||(s[23]=a(" 校对：",-1)),i(e,{href:"https://github.com/wxy"},{default:p(()=>[...s[19]||(s[19]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[26]||(s[26]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[24]||(s[24]=[a("LCTT",-1)])]),_:1}),s[27]||(s[27]=a(" 原创编译，",-1)),i(e,{href:"https://linux.cn/"},{default:p(()=>[...s[25]||(s[25]=[a("Linux中国",-1)])]),_:1}),s[28]||(s[28]=a(" 荣誉推出",-1))])])}const V=t(c,[["render",g]]);export{y as __pageData,V as default};
